INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_025_M6_S1', 'text representation', '1', 'text representation: Encoding words, tokens, or documents in forms that AI models can process computationally. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of text representation within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M6_S2', 'language models', '2', 'language models: Models that assign probabilities to sequences of language and use them to predict or generate text. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of language models within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M6_S3', 'sequence modelling', '3', 'sequence modelling: Modelling ordered observations or events so that dependencies across sequence positions can be learned and used for prediction or classification. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of sequence modelling within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M6_S4', 'parsing', '4', 'parsing: Analysing the grammatical or structural organisation of a sentence or other language sequence. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of parsing within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M6_S5', 'information extraction', '5', 'information extraction: Automatically identifying structured facts, entities, relations, or events from unstructured text. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of information extraction within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M6_S6', 'evaluation', '6', 'evaluation: Systematic assessment of an AI model or system using task-appropriate performance measures, test data, and error analysis. In Natural Language Processing, the focus is on the analysis, design, implementation, interpretation, or evaluation of evaluation within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M6_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S1', 'image formation', '1', 'image formation refers to the process by which a scene is projected and recorded as an image through an imaging system. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of image formation within Artificial Intelligence, particularly where the Computer Vision and Perception module establishes its technical context.', 'SSD_COURSE_025_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S2', 'feature extraction', '2', 'feature extraction: Computing informative image patterns such as edges, textures, shapes, or learned representations. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of feature extraction within Artificial Intelligence, particularly where the Computer Vision and Perception module establishes its technical context.', 'SSD_COURSE_025_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S3', 'classification', '3', 'classification: Assigning an input image or instance to one or more predefined categories. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of classification within Artificial Intelligence, particularly where the Computer Vision and Perception module establishes its technical context.', 'SSD_COURSE_025_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S4', 'object detection', '4', 'object detection: Locating objects in an image and assigning class labels to the detected objects. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of object detection within Artificial Intelligence, particularly where the Computer Vision and Perception module establishes its technical context.', 'SSD_COURSE_025_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S5', 'segmentation', '5', 'segmentation: Assigning labels to image pixels or regions to separate objects or semantic areas. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of segmentation within Artificial Intelligence, particularly where the Computer Vision and Perception module establishes its technical context.', 'SSD_COURSE_025_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M7_S6', 'evaluation', '6', 'evaluation: Systematic assessment of an AI model or system using task-appropriate performance measures, test data, and error analysis. In Computer Vision and Perception, the focus is on the analysis, design, implementation, interpretation, or evaluation of evaluation within Artificial Intelligence, particularly where the Natural Language Processing module establishes its technical context.', 'SSD_COURSE_025_M7_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S1', 'AI system architecture', '1', 'AI system architecture refers to the organization of models, data, software, computing resources, interfaces, and supporting services that together implement an AI system. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of AI system architecture within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S2', 'robustness', '2', 'robustness refers to the ability of an AI system to maintain acceptable performance under disturbances, uncertainty, or input variation. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of robustness within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S3', 'interpretability', '3', 'interpretability refers to the extent to which a model''s predictions or internal reasoning can be understood by people. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of interpretability within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S4', 'fairness', '4', 'fairness refers to the use of defined criteria to assess and reduce unjustified differences in model outcomes across groups. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of fairness within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S5', 'privacy', '5', 'privacy: Protection of personal or sensitive information during AI data collection, processing, storage, and use. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of privacy within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M8_S6', 'safety and governance', '6', 'safety and governance: safety and governance in Artificial Intelligence concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing safety and governance. In AI Systems, Safety and Ethics, the focus is on the analysis, design, implementation, interpretation, or evaluation of safety and governance within Artificial Intelligence, particularly where the AI Systems, Safety and Ethics module establishes its technical context.', 'SSD_COURSE_025_M8_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M1_S1', 'supervised learning', '1', 'supervised learning: Supervised learning learns a mapping from inputs to labelled outputs using observed training examples. In Learning Paradigms, the focus is on the analysis, design, implementation, interpretation, or evaluation of supervised learning within Machine Learning, particularly where the Learning Paradigms module establishes its technical context.', 'SSD_COURSE_026_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M1_S2', 'unsupervised learning', '2', 'unsupervised learning: Unsupervised learning infers structure or representations from data without target labels, including clustering and dimensionality-reduction tasks. In Learning Paradigms, the focus is on the analysis, design, implementation, interpretation, or evaluation of unsupervised learning within Machine Learning, particularly where the Learning Paradigms module establishes its technical context.', 'SSD_COURSE_026_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M1_S3', 'semi-supervised learning', '3', 'semi-supervised learning: Semi-supervised learning combines labelled and unlabelled observations to improve learning when labelled data are limited. In Learning Paradigms, the focus is on the analysis, design, implementation, interpretation, or evaluation of semi-supervised learning within Machine Learning, particularly where the Learning Paradigms module establishes its technical context.', 'SSD_COURSE_026_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M1_S4', 'self-supervised learning', '4', 'self-supervised learning: Self-supervised learning constructs learning signals from the data itself, typically by predicting withheld, transformed, or related information. In Learning Paradigms, the focus is on the analysis, design, implementation, interpretation, or evaluation of self-supervised learning within Machine Learning, particularly where the Learning Paradigms module establishes its technical context.', 'SSD_COURSE_026_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M1_S5', 'reinforcement learning', '5', 'reinforcement learning: Reinforcement learning models sequential decision making in which an agent learns a policy from interactions with an environment and feedback in the form of rewards or costs. In Learning Paradigms, the focus is on the analysis, design, implementation, interpretation, or evaluation of reinforcement learning within Machine Learning, particularly where the Learning Paradigms module establishes its technical context.', 'SSD_COURSE_026_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S1', 'data cleaning', '1', 'data cleaning: Data cleaning identifies and corrects or documents errors, inconsistencies, duplicates, invalid values, and other quality problems before analysis or modelling. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of data cleaning within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S2', 'missing values', '2', 'missing values: Missing-value handling comprises methods for diagnosing missingness and deciding whether to remove, retain, or impute incomplete observations. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of missing values within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S3', 'categorical encoding', '3', 'categorical encoding: Categorical encoding represents non-numeric categories using numerical or structured representations suitable for statistical or machine-learning models. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of categorical encoding within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S4', 'scaling', '4', 'scaling: Transforming numerical features to comparable ranges so that model training is not dominated by variable magnitude. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of scaling within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S5', 'feature selection', '5', 'feature selection: Choosing a subset of input features that preserves useful predictive information while reducing redundancy, noise, or model complexity. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of feature selection within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M2_S6', 'leakage control', '6', 'leakage control: Preventing information from the target, future observations, or evaluation data from entering model training in a way that produces overly optimistic results. In Data Preparation and Feature Engineering, the focus is on the analysis, design, implementation, interpretation, or evaluation of leakage control within Machine Learning, particularly where the Data Preparation and Feature Engineering module establishes its technical context.', 'SSD_COURSE_026_M2_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S1', 'linear regression', '1', 'linear regression refers to a regression model that represents the target as a linear function of the input features. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of linear regression within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S2', 'logistic regression', '2', 'logistic regression refers to a probabilistic classification model that relates features to class probability through the logistic function. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of logistic regression within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S3', 'regularization', '3', 'regularization: Adding a penalty or constraint to limit model complexity and reduce overfitting. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of regularization within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S4', 'decision trees', '4', 'decision trees: Models that make predictions by recursively splitting data using feature-based decision rules. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of decision trees within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S5', 'ensemble methods', '5', 'ensemble methods: Methods that combine predictions from multiple models to improve accuracy, stability, or robustness. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of ensemble methods within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M3_S6', 'support vector machines', '6', 'support vector machines: Supervised learning models that construct decision boundaries using support vectors and, when required, kernel functions to represent nonlinear relationships. In Regression and Classification, the focus is on the analysis, design, implementation, interpretation, or evaluation of support vector machines within Machine Learning, particularly where the Regression and Classification module establishes its technical context.', 'SSD_COURSE_026_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S1', 'probability models', '1', 'probability models: Mathematical models that represent uncertainty in data, variables, and relationships using probability distributions. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of probability models within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S2', 'Bayes rule', '2', 'Bayes rule refers to a rule for updating the probability of a hypothesis using observed evidence. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of Bayes rule within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S3', 'naive Bayes', '3', 'naive Bayes refers to a Bayesian classifier that assumes conditional independence among features given the class. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of naive Bayes within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S4', 'graphical models', '4', 'graphical models: Probabilistic models that represent conditional dependencies between variables using a graph. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of graphical models within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S5', 'maximum likelihood', '5', 'maximum likelihood: Estimating model parameters by choosing values that make the observed data most probable. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of maximum likelihood within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M4_S6', 'Bayesian inference', '6', 'Bayesian inference: Updating prior beliefs about model parameters using observed data to obtain a posterior distribution. In Probabilistic and Bayesian Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of Bayesian inference within Machine Learning, particularly where the Probabilistic and Bayesian Learning module establishes its technical context.', 'SSD_COURSE_026_M4_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M5_S1', 'clustering', '1', 'clustering: Grouping observations into internally similar sets without using predefined class labels. In Unsupervised Learning and Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of clustering within Machine Learning, particularly where the Unsupervised Learning and Representation module establishes its technical context.', 'SSD_COURSE_026_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M5_S2', 'dimensionality reduction', '2', 'dimensionality reduction: Representing high-dimensional data with fewer variables while retaining important structure or information. In Unsupervised Learning and Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of dimensionality reduction within Machine Learning, particularly where the Unsupervised Learning and Representation module establishes its technical context.', 'SSD_COURSE_026_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M5_S3', 'principal component analysis', '3', 'principal component analysis refers to a dimensionality-reduction method that transforms correlated variables into orthogonal principal components ordered by explained variance. In Unsupervised Learning and Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of principal component analysis within Machine Learning, particularly where the Unsupervised Learning and Representation module establishes its technical context.', 'SSD_COURSE_026_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M5_S4', 'mixture models', '4', 'mixture models: Probabilistic models that represent data as arising from a combination of component distributions. In Unsupervised Learning and Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of mixture models within Machine Learning, particularly where the Unsupervised Learning and Representation module establishes its technical context.', 'SSD_COURSE_026_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M5_S5', 'manifold learning', '5', 'manifold learning: Nonlinear dimensionality-reduction methods that model data as lying near a lower-dimensional manifold. In Unsupervised Learning and Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of manifold learning within Machine Learning, particularly where the Unsupervised Learning and Representation module establishes its technical context.', 'SSD_COURSE_026_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M6_S1', 'perceptrons', '1', 'perceptrons: Single-layer threshold-based units that form the basic computational model of a linear classifier. In Neural Networks and Deep Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of perceptrons within Machine Learning, particularly where the Neural Networks and Deep Learning module establishes its technical context.', 'SSD_COURSE_026_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M6_S2', 'multilayer networks', '2', 'multilayer networks: Neural networks containing successive layers of interconnected units that learn nonlinear mappings. In Neural Networks and Deep Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of multilayer networks within Machine Learning, particularly where the Neural Networks and Deep Learning module establishes its technical context.', 'SSD_COURSE_026_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M6_S3', 'backpropagation', '3', 'backpropagation refers to an algorithm that computes gradients through a neural network so its parameters can be updated during training. In Neural Networks and Deep Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of backpropagation within Machine Learning, particularly where the Neural Networks and Deep Learning module establishes its technical context.', 'SSD_COURSE_026_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_026_M6_S4', 'convolutional networks', '4', 'convolutional networks: Neural networks using convolutional filters to learn local spatial or temporal patterns. In Neural Networks and Deep Learning, the focus is on the analysis, design, implementation, interpretation, or evaluation of convolutional networks within Machine Learning, particularly where the Neural Networks and Deep Learning module establishes its technical context.', 'SSD_COURSE_026_M6_S4', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;